/*
 * A267814  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 221" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A267814
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(n) = 0 if n == r*(r+1)-1 for some r ≥ 1 (the zero in each
 *            row), otherwise 1
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence starts: 1,0,1,1,1,0,1,1,1,1,1,0,1,1,1,1,1,1,1,0,… */

#include <stdint.h>

/* Integer square root for uint64_t using binary search.
   The result satisfies r² ≤ n < (r+1)². */
static idx_t my_isqrt(idx_t n)
{
    if (n < 2) return n;
    idx_t lo = 0;
    idx_t hi = (n < 0xFFFFFFFFULL) ? n : 0xFFFFFFFFULL; /* sqrt(n) ≤ 2³²-1 */
    while (lo <= hi) {
        idx_t mid = (lo + hi) >> 1;
        idx_t sq  = mid * mid;                 /* fits in 64 bits */
        if (sq == n) return mid;
        if (sq < n)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return hi;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)1;        /* first row, single 1 */

    idx_t r   = my_isqrt(n);            /* row index: floor(sqrt(n))   */
    idx_t pos = n - r * r;              /* position within the row    */
    if (pos == r - 1) return (seq_t)0;  /* the single zero in the row */
    return (seq_t)1;                    /* all other entries are 1    */
}
